import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';

import { useUsers } from '../api/get-users';
import { useUpdateUserRole } from '../api/update-role';

import { DeleteUser } from './delete-user';

export const UsersList = () => {
  const usersQuery = useUsers();
  const updateRoleMutation = useUpdateUserRole();

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  const handleRoleChange = (userId: string, role: string) => {
    updateRoleMutation.mutate({ 
      id: userId, 
      data: { role: role as 'ADMIN' | 'USER' } 
    });
  };

  return (
    <Table
      data={users}
      columns={[
        {
          title: 'First Name',
          field: 'firstName',
        },
        {
          title: 'Last Name',
          field: 'lastName',
        },
        {
          title: 'Email',
          field: 'email',
        },
        {
          title: 'Role',
          field: 'role',
          Cell({ entry }) {
            if (!entry?.id || !entry?.role) return <span>{entry?.role}</span>;
            return (
              <select
                value={entry.role}
                onChange={(e) => handleRoleChange(entry.id, e.target.value)}
                disabled={updateRoleMutation.isLoading && updateRoleMutation.variables?.id === entry.id}
                className="rounded border border-gray-300 px-2 py-1 text-sm focus:border-blue-500 focus:ring-blue-500 w-full"
              >
                <option value="ADMIN">Admin</option>
                <option value="USER">User</option>
              </select>
            );
          },
        },
        {
          title: 'Created At',
          field: 'createdAt',
          Cell({ entry: { createdAt } }) {
            return <span>{formatDate(createdAt)}</span>;
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return <DeleteUser id={id} />;
          },
        },
      ]}
    />
  );
};

